from itertools import product
import heapq


def _rounded(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, sequence_first, discounted, refunds, half_up_enabled):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            rank = (sequence, event.get("revision", 0), pos)
        else:
            rank = (event.get("revision", 0), pos)
        if event_id not in winners or rank > winners[event_id][0]:
            winners[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data.get("rounding", "floor")
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), 10000,
                       mode if half_up_enabled else "floor")
        base = net if discounted else raw
        tax = _rounded(base * event.get("tax_bp", 0), 10000,
                       mode if half_up_enabled else "floor")
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_ledger(sequence_first=False, discounted=False, refunds=True,
                  half_up_enabled=True):
    return lambda data: _ledger(data, sequence_first, discounted, refunds,
                                half_up_enabled)


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}

    # Descending vectors, with an absent package ranked below every version.
    choices = []
    for name in names:
        versions = sorted(rows[name], reverse=True)
        choices.append(versions + [-1])

    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values)
                    if version != -1}
        if any(name not in selected for name in data.get("roots", {})):
            continue
        invalid = False
        for name, version in selected.items():
            if version in blocked.get(name, []):
                invalid = True
                break
            if name in pins and version != pins[name]:
                invalid = True
                break
        if invalid:
            continue

        constraints = {name: [] for name in selected}
        for name, bounds in data.get("roots", {}).items():
            constraints[name].append(tuple(bounds))
        graph = {name: [] for name in selected}
        closure = set(data.get("roots", {}))
        pending = list(closure)
        while pending and not invalid:
            name = pending.pop()
            version = selected.get(name)
            if version is None:
                invalid = True
                break
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in selected:
                    invalid = True
                    break
                constraints[other].append((dep["min"], dep["max"]))
                graph[name].append(other)
                if other not in closure:
                    closure.add(other)
                    pending.append(other)
        if invalid or closure != set(selected):
            continue
        for name, version in selected.items():
            if any(not low <= version <= high
                   for low, high in constraints[name]):
                invalid = True
                break
        if invalid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in graph[name]:
                if not visit(other):
                    return False
            state[name] = 2
            return True
        if not all(visit(name) for name in selected):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        valid = True
        for i, first in enumerate(ordered):
            overlap = sum(first["start"] < other["end"] and
                          other["start"] < first["end"]
                          for other in ordered)
            if overlap > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in chosen)
        id_list = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    index = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = sum(1 << index[node] for node in {start_node} if node in index)
    remaining = data["coupons"]
    start_time = data["start"]
    distances = {(start_node, initial_mask, remaining): start_time}
    queue = [(start_time, start_node, initial_mask, remaining)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], left)]
            if left:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
            next_node = edge["v"]
            next_mask = mask | ((1 << index[next_node]) if next_node in index else 0)
            for duration, next_left in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, next_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_left))
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_ledger(False, False, True, True),
    "component_02": _build_ledger(True, False, True, True),
    "component_03": _build_ledger(False, True, True, True),
    "component_04": _build_ledger(True, True, True, True),
